// 经典：两数之和
vector<int> twoSum(vector<int>& nums, int target) {
    unordered_map<int, int> idx; // value -> index
    for (int i = 0; i < (int)nums.size(); i++) {
        int need = target - nums[i];
        if (idx.count(need)) return {idx[need], i};
        idx[nums[i]] = i;
    }
    return {};
}

