// Top K 大元素（用小顶堆）
vector<int> topK(vector<int>& nums, int k) {
    priority_queue<int, vector<int>, greater<int>> heap;
    for (int x : nums) {
        heap.push(x);
        if ((int)heap.size() > k) heap.pop();
    }
    vector<int> ans;
    while (!heap.empty()) { ans.push_back(heap.top()); heap.pop(); }
    return ans;
}

