using namespace std;

struct DSU {
    vector<int> fa;
    DSU(int n) : fa(n + 1) { iota(fa.begin(), fa.end(), 0); }
    int find(int x) { return fa[x] == x ? x : fa[x] = find(fa[x]); }
    void unite(int x, int y) { fa[find(x)] = find(y); }
};

// Kruskal：返回最小生成树总权值（不连通返回 -1）
struct Edge { int u, v, w; };
int kruskal(int n, vector<Edge>& edges) {
    sort(edges.begin(), edges.end(),
         [](Edge& a, Edge& b) { return a.w < b.w; });
    DSU dsu(n);
    int sum = 0, cnt = 0;
    for (auto& e : edges) {
        if (dsu.find(e.u) != dsu.find(e.v)) {
            dsu.unite(e.u, e.v);
            sum += e.w;
            if (++cnt == n - 1) break;
        }
    }
    return cnt == n - 1 ? sum : -1;
}

// Prim（堆优化）：返回最小生成树总权值
int prim(int n, vector<pair<int,int>> g[]) {
    vector<bool> in(n + 1, false);
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;
    pq.push({0, 1});
    int sum = 0, cnt = 0;
    while (!pq.empty() && cnt < n) {
        auto [w, u] = pq.top(); pq.pop();
        if (in[u]) continue;
        in[u] = true; sum += w; cnt++;
        for (auto [v, ww] : g[u])
            if (!in[v]) pq.push({ww, v});
    }
    return cnt == n ? sum : -1;
}

