const long long INF = 0x3f3f3f3f3f3f3f3fLL;

// SPFA：返回起点到各点最短路；存在负环返回 false
bool spfa(int n, vector<pair<int,int>> g[], int s, vector<long long>& dist) {
    dist.assign(n + 1, INF);
    vector<bool> inq(n + 1, false);
    vector<int> cnt(n + 1, 0); // 入队次数，用于判负环
    queue<int> q;
    dist[s] = 0; q.push(s); inq[s] = true;
    while (!q.empty()) {
        int u = q.front(); q.pop(); inq[u] = false;
        for (auto [v, w] : g[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                if (!inq[v]) {
                    q.push(v); inq[v] = true;
                    if (++cnt[v] >= n) return false; // 负环
                }
            }
        }
    }
    return true;
}

