// 01 背包：容量 C，物品重量 w、价值 v
int knapsack01(vector<int>& w, vector<int>& v, int C) {
    vector<int> dp(C + 1, 0);
    for (int i = 0; i < (int)w.size(); i++)
        for (int j = C; j >= w[i]; j--)      // 倒序
            dp[j] = max(dp[j], dp[j - w[i]] + v[i]);
    return dp[C];
}

// 完全背包：每种物品无限件
int knapsackComplete(vector<int>& w, vector<int>& v, int C) {
    vector<int> dp(C + 1, 0);
    for (int i = 0; i < (int)w.size(); i++)
        for (int j = w[i]; j <= C; j++)      // 正序
            dp[j] = max(dp[j], dp[j - w[i]] + v[i]);
    return dp[C];
}

// 多重背包：每种物品限 s 件（二进制拆分转 01）
int knapsackMultiple(vector<int>& w, vector<int>& v, vector<int>& s, int C) {
    vector<int> nw, nv;
    for (int i = 0; i < (int)w.size(); i++) {
        int k = 1;
        while (k <= s[i]) {
            nw.push_back(w[i] * k);
            nv.push_back(v[i] * k);
            s[i] -= k; k <<= 1;
        }
        if (s[i] > 0) { nw.push_back(w[i] * s[i]); nv.push_back(v[i] * s[i]); }
    }
    return knapsack01(nw, nv, C);
}

