// pos: 当前位；limit: 是否顶格（受上界限制）
int dfs(int pos, bool limit, const string& s) {
    if (pos == (int)s.size()) return 1;
    if (!limit && memo[pos] != -1) return memo[pos];
    int up = limit ? s[pos] - '0' : 9;
    int res = 0;
    for (int d = 0; d <= up; d++) {
        if (d == 4) continue; // 跳过含 4
        res += dfs(pos + 1, limit && (d == up), s);
    }
    if (!limit) memo[pos] = res;
    return res;
}

