const long long MOD = 1e9 + 7;
using Mat = vector<vector<long long>>;

// 矩阵乘法
Mat mul(const Mat& a, const Mat& b) {
    int n = a.size(), m = b[0].size(), k = b.size();
    Mat c(n, vector<long long>(m, 0));
    for (int i = 0; i < n; i++)
        for (int p = 0; p < k; p++)
            for (int j = 0; j < m; j++)
                c[i][j] = (c[i][j] + a[i][p] * b[p][j]) % MOD;
    return c;
}

// 矩阵快速幂
Mat matPow(Mat base, long long exp) {
    int n = base.size();
    Mat res(n, vector<long long>(n, 0));
    for (int i = 0; i < n; i++) res[i][i] = 1; // 单位矩阵
    while (exp > 0) {
        if (exp & 1) res = mul(res, base);
        base = mul(base, base);
        exp >>= 1;
    }
    return res;
}

// 斐波那契第 n 项（F0=0, F1=1）
long long fib(long long n) {
    if (n == 0) return 0;
    Mat base = {{1, 1}, {1, 0}};
    Mat t = matPow(base, n - 1);
    return t[0][0]; // F_n
}

