const int N = 1e5 + 10;
vector<int> g[N];
int dfn[N], low[N], scc[N];
bool inStack[N];
stack<int> st;
int timer = 0, sccCnt = 0;

void tarjan(int u) {
    dfn[u] = low[u] = ++timer;
    st.push(u);
    inStack[u] = true;
    for (int v : g[u]) {
        if (!dfn[v]) {
            tarjan(v);
            low[u] = min(low[u], low[v]);
        } else if (inStack[v]) {
            low[u] = min(low[u], dfn[v]);
        }
    }
    if (dfn[u] == low[u]) {
        sccCnt++;
        while (true) {
            int v = st.top(); st.pop();
            inStack[v] = false;
            scc[v] = sccCnt;
            if (v == u) break;
        }
    }
}

