// 树状数组：单点加、前缀和查询（1-based）
struct Fenwick {
    int n;
    vector<long long> tr;
    Fenwick(int n) : n(n), tr(n + 1, 0) {}
    int lowbit(int x) { return x & -x; }
    void add(int x, long long v) {           // 单点加
        for (int i = x; i <= n; i += lowbit(i)) tr[i] += v;
    }
    long long sum(int x) {                    // 前缀和 [1..x]
        long long res = 0;
        for (int i = x; i > 0; i -= lowbit(i)) res += tr[i];
        return res;
    }
    long long query(int l, int r) {           // 区间和 [l..r]
        return sum(r) - sum(l - 1);
    }
};

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

// 线段树：区间加 + 区间求和（懒标记）
struct SegTree {
    int n;
    vector<ll> sum, add;
    SegTree(int n, vector<int>& a) : n(n), sum(n * 4, 0), add(n * 4, 0) {
        build(1, 1, n, a);
    }
    void build(int p, int l, int r, vector<int>& a) {
        if (l == r) { sum[p] = a[l]; return; }
        int mid = (l + r) >> 1;
        build(p << 1, l, mid, a);
        build(p << 1 | 1, mid + 1, r, a);
        sum[p] = sum[p << 1] + sum[p << 1 | 1];
    }
    void pushdown(int p, int l, int r) {
        if (!add[p]) return;
        int mid = (l + r) >> 1;
        int lc = p << 1, rc = p << 1 | 1;
        add[lc] += add[p]; sum[lc] += add[p] * (mid - l + 1);
        add[rc] += add[p]; sum[rc] += add[p] * (r - mid);
        add[p] = 0;
    }
    void update(int p, int l, int r, int ql, int qr, ll v) {
        if (ql <= l && r <= qr) { add[p] += v; sum[p] += v * (r - l + 1); return; }
        pushdown(p, l, r);
        int mid = (l + r) >> 1;
        if (ql <= mid) update(p << 1, l, mid, ql, qr, v);
        if (qr > mid) update(p << 1 | 1, mid + 1, r, ql, qr, v);
        sum[p] = sum[p << 1] + sum[p << 1 | 1];
    }
    ll query(int p, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) return sum[p];
        pushdown(p, l, r);
        int mid = (l + r) >> 1;
        ll res = 0;
        if (ql <= mid) res += query(p << 1, l, mid, ql, qr);
        if (qr > mid) res += query(p << 1 | 1, mid + 1, r, ql, qr);
        return res;
    }
};

