// 主席树：静态区间第 k 小
const int N = 2e5 + 10;
int root[N], ls[N * 25], rs[N * 25], sum[N * 25], idx = 0;

int build(int l, int r) {
    int p = ++idx;
    if (l == r) return p;
    int mid = (l + r) >> 1;
    ls[p] = build(l, mid);
    rs[p] = build(mid + 1, r);
    return p;
}

int update(int pre, int l, int r, int pos) {
    int p = ++idx;
    ls[p] = ls[pre]; rs[p] = rs[pre]; sum[p] = sum[pre] + 1;
    if (l == r) return p;
    int mid = (l + r) >> 1;
    if (pos <= mid) ls[p] = update(ls[pre], l, mid, pos);
    else rs[p] = update(rs[pre], mid + 1, r, pos);
    return p;
}

int query(int u, int v, int l, int r, int k) {
    if (l == r) return l;
    int mid = (l + r) >> 1;
    int cnt = sum[ls[v]] - sum[ls[u]];
    if (k <= cnt) return query(ls[u], ls[v], l, mid, k);
    return query(rs[u], rs[v], mid + 1, r, k - cnt);
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

struct Dinic {
    struct Edge { int to, rev; ll cap; };
    int n;
    vector<vector<Edge>> g;
    vector<int> level, iter;
    Dinic(int n) : n(n), g(n + 1), level(n + 1), iter(n + 1) {}
    void addEdge(int u, int v, ll c) {
        g[u].push_back({v, (int)g[v].size(), c});
        g[v].push_back({u, (int)g[u].size() - 1, 0});
    }
    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q; q.push(s); level[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& e : g[u]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }
    ll dfs(int u, int t, ll f) {
        if (u == t) return f;
        for (int& i = iter[u]; i < (int)g[u].size(); i++) {
            Edge& e = g[u][i];
            if (e.cap > 0 && level[u] < level[e.to]) {
                ll d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }
    ll maxflow(int s, int t) {
        ll flow = 0;
        while (bfs(s, t)) {
            fill(iter.begin(), iter.end(), 0);
            ll f;
            while ((f = dfs(s, t, 1e18)) > 0) flow += f;
        }
        return flow;
    }
};

