// Z 函数：z[i] = s 与 s[i..] 的最长公共前缀长度
vector<int> zFunction(const string& s) {
    int n = s.size();
    vector<int> z(n);
    for (int i = 1, l = 0, r = 0; i < n; i++) {
        if (i <= r) z[i] = min(r - i + 1, z[i - l]);
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;
        if (i + z[i] - 1 > r) { l = i; r = i + z[i] - 1; }
    }
    return z;
}

#include <bits/stdc++.h>
using namespace std;

// 后缀数组（倍增 + 基数排序），返回 sa（1-based）
vector<int> buildSA(const string& s) {
    int n = s.size(), m = 256;
    vector<int> sa(n + 1), rk(2 * n + 1), oldrk(2 * n + 1), id(n + 1);
    vector<int> cnt(max(n, m) + 1);
    for (int i = 1; i <= n; i++) rk[i] = (unsigned char)s[i - 1];
    for (int i = 1; i <= n; i++) cnt[rk[i]]++;
    for (int i = 1; i <= m; i++) cnt[i] += cnt[i - 1];
    for (int i = n; i >= 1; i--) sa[cnt[rk[i]]--] = i;
    for (int k = 1; k < n; k <<= 1) {
        int p = 0;
        for (int i = n - k + 1; i <= n; i++) id[++p] = i;
        for (int i = 1; i <= n; i++) if (sa[i] > k) id[++p] = sa[i] - k;
        fill(cnt.begin(), cnt.end(), 0);
        for (int i = 1; i <= n; i++) cnt[rk[id[i]]]++;
        for (int i = 1; i <= m; i++) cnt[i] += cnt[i - 1];
        for (int i = n; i >= 1; i--) sa[cnt[rk[id[i]]]--] = id[i];
        swap(rk, oldrk);
        p = 0;
        for (int i = 1; i <= n; i++) {
            if (oldrk[sa[i]] == oldrk[sa[i - 1]] && oldrk[sa[i] + k] == oldrk[sa[i - 1] + k])
                rk[sa[i]] = p;
            else rk[sa[i]] = ++p;
        }
        m = p;
        if (m == n) break;
    }
    return sa;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 1e5 + 10;
vector<pair<int,int>> g[N]; // (to, weight)
bool vis[N];
int sz[N], maxp[N];

void dfsSz(int u, int fa) {
    sz[u] = 1; maxp[u] = 0;
    for (auto& e : g[u]) {
        int v = e.first;
        if (v == fa || vis[v]) continue;
        dfsSz(v, u);
        sz[u] += sz[v];
        maxp[u] = max(maxp[u], sz[v]);
    }
}

int getCentroid(int u, int fa, int total) {
    maxp[u] = max(maxp[u], total - sz[u]);
    int res = u;
    for (auto& e : g[u]) {
        int v = e.first;
        if (v == fa || vis[v]) continue;
        int c = getCentroid(v, u, total);
        if (maxp[c] < maxp[res]) res = c;
    }
    return res;
}

void solve(int u) {
    dfsSz(u, 0);
    int c = getCentroid(u, 0, sz[u]);
    vis[c] = true;
    // ... 统计经过 c 的路径 ...
    for (auto& e : g[c]) {
        int v = e.first;
        if (vis[v]) continue;
        solve(v); // 递归处理子树
    }
}

#include <bits/stdc++.h>
using namespace std;

struct Point { long long x, y; };
Point operator-(Point a, Point b) { return {a.x - b.x, a.y - b.y}; }
long long cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }

// Andrew 算法求凸包（逆时针，顶点列表，不含重复起点）
vector<Point> convexHull(vector<Point> p) {
    sort(p.begin(), p.end(), [](Point a, Point b) {
        return a.x != b.x ? a.x < b.x : a.y < b.y;
    });
    int n = p.size();
    if (n <= 2) return p;
    vector<Point> stk;
    for (int i = 0; i < n; i++) {
        while (stk.size() >= 2 &&
               cross(stk.back() - stk[stk.size() - 2], p[i] - stk[stk.size() - 2]) <= 0)
            stk.pop_back();
        stk.push_back(p[i]);
    }
    int lower = stk.size();
    for (int i = n - 2; i >= 0; i--) {
        while ((int)stk.size() > lower &&
               cross(stk.back() - stk[stk.size() - 2], p[i] - stk[stk.size() - 2]) <= 0)
            stk.pop_back();
        stk.push_back(p[i]);
    }
    stk.pop_back(); // 去掉重复的起点
    return stk;
}

