#include <bits/stdc++.h>
using namespace std;
using ll = long long;

// 1. gcd
ll gcd(ll a, ll b) { return b ? gcd(b, a % b) : a; }

// 2. exgcd: ax + by = gcd(a,b), 返回 gcd
ll exgcd(ll a, ll b, ll &x, ll &y) {
    if (!b) { x = 1; y = 0; return a; }
    ll d = exgcd(b, a % b, y, x);
    y -= a / b * x;
    return d;
}

// 3. 快速幂
ll qpow(ll a, ll b, ll mod) {
    ll r = 1 % mod; a %= mod;
    while (b) { if (b & 1) r = r * a % mod; a = a * a % mod; b >>= 1; }
    return r;
}

// 4. 模逆元（mod 为素数时用费马小定理）
ll modInv(ll a, ll mod) { return qpow(a, mod - 2, mod); }

// 5. 线性筛素数 + 欧拉函数
const int N = 1e6 + 5;
vector<int> primes;
bool isComp[N];
int phi[N];

void sieve(int n) {
    phi[1] = 1;
    for (int i = 2; i <= n; i++) {
        if (!isComp[i]) { primes.push_back(i); phi[i] = i - 1; }
        for (int p : primes) {
            if ((ll)i * p > n) break;
            isComp[i * p] = true;
            if (i % p == 0) { phi[i * p] = phi[i] * p; break; }
            else phi[i * p] = phi[i] * (p - 1);
        }
    }
}

int main() {
    // 示例：解 3x ≡ 2 (mod 5)
    ll x, y;
    ll d = exgcd(3, 5, x, y);  // d = gcd(3,5) = 1
    // 3x + 5y = 1，两边乘 2 得 3(2x) ≡ 2 (mod 5)
    cout << "x = " << (x % 5 + 5) % 5 << endl;  // 一组解
    sieve(100);
    cout << "phi(10) = " << phi[10] << endl;  // 4
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const int MOD = 1e9 + 7, N = 1e6 + 5;
ll fac[N], invFac[N];

ll qpow(ll a, ll b) {
    ll r = 1; a %= MOD;
    while (b) { if (b & 1) r = r * a % MOD; a = a * a % MOD; b >>= 1; }
    return r;
}

void init() {
    fac[0] = 1;
    for (int i = 1; i < N; i++) fac[i] = fac[i-1] * i % MOD;
    invFac[N-1] = qpow(fac[N-1], MOD - 2);
    for (int i = N-2; i >= 0; i--) invFac[i] = invFac[i+1] * (i+1) % MOD;
}

ll C(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fac[n] * invFac[k] % MOD * invFac[n-k] % MOD;
}

// Lucas 定理（n 极大时）
ll lucas(ll n, ll k) {
    if (k == 0) return 1;
    return C(n % MOD, k % MOD) * lucas(n / MOD, k / MOD) % MOD;
}

// 卡特兰数第 n 项
ll catalan(int n) {
    return C(2*n, n) * qpow(n + 1, MOD - 2) % MOD;
}

// 错排数 D[n]
ll derangement(int n) {
    vector<ll> D(n+1);
    D[0] = 1; D[1] = 0;
    for (int i = 2; i <= n; i++)
        D[i] = (i - 1) * (D[i-1] + D[i-2]) % MOD;
    return D[n];
}

int main() {
    init();
    cout << "C(5,2) = " << C(5,2) << endl;          // 10
    cout << "catalan(3) = " << catalan(3) << endl;    // 5
    cout << "derangement(3) = " << derangement(3) << endl; // 2
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// TSP 模板：n 个城市，从 0 出发经过所有城市回到 0 的最短路
struct TSP {
    int n;
    vector<vector<int>> dist;
    vector<vector<int>> dp;
    TSP(int n, vector<vector<int>> d) : n(n), dist(d), dp(1<<n, vector<int>(n, 1e9)) {}

    int solve() {
        int FULL = (1 << n) - 1;
        dp[1][0] = 0;
        for (int mask = 1; mask <= FULL; mask++) {
            for (int i = 0; i < n; i++) {
                if (!(mask & (1 << i)) || dp[mask][i] == 1e9) continue;
                for (int j = 0; j < n; j++) {
                    if (mask & (1 << j)) continue;
                    int nm = mask | (1 << j);
                    dp[nm][j] = min(dp[nm][j], dp[mask][i] + dist[i][j]);
                }
            }
        }
        int ans = 1e9;
        for (int i = 1; i < n; i++)
            ans = min(ans, dp[FULL][i] + dist[i][0]);
        return ans;
    }
};

// 工作分配：n 人 n 工作，最小代价
int assignWork(vector<vector<int>>& cost) {
    int n = cost.size();
    vector<int> dp(1 << n, 1e9);
    dp[0] = 0;
    for (int mask = 0; mask < (1<<n); mask++) {
        int i = __builtin_popcount(mask);  // 前 i 个人已分配
        for (int j = 0; j < n; j++) {
            if (mask & (1 << j)) continue;
            dp[mask | (1<<j)] = min(dp[mask | (1<<j)], dp[mask] + cost[i][j]);
        }
    }
    return dp[(1<<n) - 1];
}

int main() {
    // 示例：3 城市 TSP
    vector<vector<int>> d = {{0,1,2},{1,0,3},{2,3,0}};
    TSP tsp(3, d);
    cout << "TSP = " << tsp.solve() << endl;  // 0->1->2->0 = 1+3+2=6

    vector<vector<int>> cost = {{1,2},{3,4}};
    cout << "assign = " << assignWork(cost) << endl;  // 人0做工作0(1)+人1做工作1(4)=5
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// 1. 抛硬币连续 k 次正面的期望次数（递推）
double coinExpect(int k) {
    vector<double> E(k + 1, 0);
    // E[i] = 已有 i 次连续正面，到 k 次的期望次数
    // E[i] = 1 + 0.5*E[i+1] + 0.5*E[0]  (i < k)
    // 这是有后效性的（E[i] 依赖 E[0]），用代入法解：
    // 令 E[i] = a[i]*E[0] + b[i]，递推 a,b
    vector<double> a(k+1), b(k+1);
    a[k] = 0; b[k] = 0;
    for (int i = k-1; i >= 0; i--) {
        a[i] = 0.5 * a[i+1] + 0.5;
        b[i] = 1 + 0.5 * b[i+1];
    }
    // E[0] = a[0]*E[0] + b[0] => E[0] = b[0]/(1-a[0])
    return b[0] / (1 - a[0]);
}

// 2. DAG 上的期望：从起点到终点的期望路径长度
// 假设图是 DAG，dp[u] = 从 u 到终点的期望距离
double dagExpect(int n, vector<vector<pair<int,double>>>& adj, int s, int t) {
    vector<double> dp(n, 0);
    vector<int> deg(n, 0);
    for (int u = 0; u < n; u++) deg[u] = adj[u].size();
    // 按拓扑序倒推（此处简化：假设节点已按拓扑序编号，大的在前）
    dp[t] = 0;
    for (int u = n-1; u >= 0; u--) {
        if (u == t || deg[u] == 0) continue;
        double sum = 0;
        for (auto& [v, w] : adj[u]) sum += w + dp[v];
        dp[u] = sum / deg[u];
    }
    return dp[s];
}

// 3. 高斯消元（用于有后效性的期望 DP）
void gauss(vector<vector<double>>& a, int n) {
    for (int i = 0; i < n; i++) {
        int pivot = i;
        for (int j = i+1; j < n; j++)
            if (fabs(a[j][i]) > fabs(a[pivot][i])) pivot = j;
        swap(a[i], a[pivot]);
        for (int j = i+1; j <= n; j++) a[i][j] /= a[i][i];
        a[i][i] = 1;
        for (int j = 0; j < n; j++) {
            if (j == i || fabs(a[j][i]) < 1e-9) continue;
            double f = a[j][i];
            for (int k = i; k <= n; k++) a[j][k] -= f * a[i][k];
        }
    }
}

int main() {
    cout << "连续2次正面期望: " << coinExpect(2) << endl;  // 6
    cout << "连续3次正面期望: " << coinExpect(3) << endl;  // 14
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 1e5 + 5, LOG = 17;
vector<int> adj[N];
int up[N][LOG], dep[N];

void dfs(int u, int fa) {
    up[u][0] = fa;
    for (int k = 1; k < LOG; k++)
        up[u][k] = up[up[u][k-1]][k-1];
    for (int v : adj[u]) {
        if (v == fa) continue;
        dep[v] = dep[u] + 1;
        dfs(v, u);
    }
}

int lca(int u, int v) {
    if (dep[u] < dep[v]) swap(u, v);
    int diff = dep[u] - dep[v];
    for (int k = 0; k < LOG; k++)
        if (diff & (1 << k)) u = up[u][k];
    if (u == v) return u;
    for (int k = LOG - 1; k >= 0; k--)
        if (up[u][k] != up[v][k]) { u = up[u][k]; v = up[v][k]; }
    return up[u][0];
}

int dist(int u, int v) {
    return dep[u] + dep[v] - 2 * dep[lca(u, v)];
}

// 树上点差分：路径 u->v 所有点 +1
int diff[N];
void addPath(int u, int v) {
    int w = lca(u, v);
    diff[u]++; diff[v]++;
    diff[w]--;
    if (up[w][0] != w) diff[up[w][0]]--;  // 根的父亲是自己
}

// DFS 求子树和（差分还原）
int val[N];
void dfsSum(int u, int fa) {
    val[u] = diff[u];
    for (int v : adj[u]) {
        if (v == fa) continue;
        dfsSum(v, u);
        val[u] += val[v];
    }
}

int main() {
    // 示例：7 个节点的树
    int edges[6][2] = {{1,2},{1,3},{2,4},{2,5},{3,6},{3,7}};
    for (auto& [u,v] : edges) { adj[u].push_back(v); adj[v].push_back(u); }
    dep[1] = 0;
    dfs(1, 1);  // 根的父亲设为自己
    cout << "LCA(4,5) = " << lca(4,5) << endl;  // 2
    cout << "LCA(4,6) = " << lca(4,6) << endl;  // 1
    cout << "dist(4,6) = " << dist(4,6) << endl; // 4
    return 0;
}

