#include <bits/stdc++.h>
using namespace std;
using ll = long long;

// 1. 快速幂
ll qpow(ll a, ll b, ll mod) {
    ll r = 1 % mod; a %= mod;
    while (b) { if (b & 1) r = r * a % mod; a = a * a % mod; b >>= 1; }
    return r;
}

// 2. ST 表（区间最大值）
const int N = 1e5 + 5, LOG = 17;
int st[LOG][N], lg[N];

void buildST(int a[], int n) {
    lg[1] = 0;
    for (int i = 2; i <= n; i++) lg[i] = lg[i/2] + 1;
    for (int i = 1; i <= n; i++) st[0][i] = a[i];
    for (int k = 1; k < LOG; k++)
        for (int i = 1; i + (1<<k) - 1 <= n; i++)
            st[k][i] = max(st[k-1][i], st[k-1][i + (1<<(k-1))]);
}

int queryMax(int l, int r) {
    int k = lg[r - l + 1];
    return max(st[k][l], st[k][r - (1<<k) + 1]);
}

// 3. 倍增求函数迭代：f(x) = (a*x + b) % mod，求 f^k(x)
struct FuncIter {
    ll a, b, mod;
    // 倍增：f^(2^k)(x) = A_k * x + B_k
    // f^2(x) = a*(a*x+b)+b = a^2*x + a*b+b
    vector<ll> A, B;  // A[k], B[k] 表示 f^(2^k)
    FuncIter(ll a, ll b, ll mod) : a(a), b(b), mod(mod) {
        A.assign(60, 0); B.assign(60, 0);
        A[0] = a % mod; B[0] = b % mod;
        for (int k = 1; k < 60; k++) {
            A[k] = A[k-1] * A[k-1] % mod;
            B[k] = (A[k-1] * B[k-1] + B[k-1]) % mod;
        }
    }
    ll apply(ll x, ll k) {  // f^k(x)
        for (int i = 0; i < 60; i++)
            if (k & (1LL << i)) x = (A[i] * x + B[i]) % mod;
        return x;
    }
};

int main() {
    cout << "2^10 mod 1e9+7 = " << qpow(2, 10, 1e9+7) << endl;  // 1024

    int a[] = {0, 3, 1, 4, 1, 5, 9, 2, 6};  // 1-indexed
    buildST(a, 8);
    cout << "max(2,6) = " << queryMax(2, 6) << endl;  // max(1,4,1,5,9)=9

    FuncIter fi(2, 3, 100);  // f(x)=2x+3 mod 100
    cout << "f^3(1) = " << fi.apply(1, 3) << endl;  // f(1)=5, f(5)=13, f(13)=29
    return 0;
}

