#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1e9 + 7;

// 1. 普通快速幂
ll qpow(ll a, ll b, ll mod) {
    ll res = 1 % mod; a %= mod;
    while (b) { if (b & 1) res = res * a % mod; a = a * a % mod; b >>= 1; }
    return res;
}

// 2. 快速乘（mod 极大时防溢出）
ll qmul(ll a, ll b, ll mod) {
    ll res = 0;
    while (b) { if (b & 1) res = (res + a) % mod; a = (a + a) % mod; b >>= 1; }
    return res;
}

// 3. 模逆元（mod 为素数）
ll modInv(ll a, ll mod) { return qpow(a, mod - 2, mod); }

// 4. 矩阵快速幂
struct Matrix {
    int n;
    vector<vector<ll>> a;
    Matrix(int n) : n(n), a(n, vector<ll>(n, 0)) {}
    Matrix operator*(const Matrix& o) const {
        Matrix r(n);
        for (int i = 0; i < n; i++)
            for (int k = 0; k < n; k++)
                for (int j = 0; j < n; j++)
                    r.a[i][j] = (r.a[i][j] + a[i][k] * o.a[k][j]) % MOD;
        return r;
    }
};

Matrix matPow(Matrix a, ll b) {
    Matrix r(a.n);
    for (int i = 0; i < a.n; i++) r.a[i][i] = 1;
    while (b) { if (b & 1) r = r * a; a = a * a; b >>= 1; }
    return r;
}

// 斐波那契第 n 项（F(0)=0, F(1)=1）
ll fib(ll n) {
    if (n == 0) return 0;
    Matrix m(2);
    m.a[0][0] = 1; m.a[0][1] = 1;
    m.a[1][0] = 1; m.a[1][1] = 0;
    Matrix r = matPow(m, n - 1);
    return r.a[0][0];  // F(n)
}

int main() {
    cout << "2^10 mod 1e9+7 = " << qpow(2, 10, MOD) << endl;  // 1024
    cout << "3^(-1) mod 7 = " << modInv(3, 7) << endl;  // 5 (3*5=15≡1 mod7)
    cout << "fib(10) = " << fib(10) << endl;  // 55
    cout << "fib(50) = " << fib(50) << endl;  // 12586269025 mod 1e9+7
    return 0;
}

