        }
    }
    return true;
}

// 2. 模意义下高斯消元
bool gaussMod(vector<vector<ll>>& a, int n) {
    for (int i = 0; i < n; i++) {
        int pivot = i;
        for (int j = i+1; j < n; j++)
            if (a[j][i] > a[pivot][i]) pivot = j;
        swap(a[i], a[pivot]);
        if (a[i][i] == 0) return false;
        ll inv = modInv(a[i][i]);
        for (int j = i+1; j < n; j++) {
            ll f = a[j][i] * inv % MOD;
            for (int k = i; k <= n; k++)
                a[j][k] = (a[j][k] - f * a[i][k] % MOD + MOD) % MOD;
        }
    }
    for (int i = n-1; i >= 0; i--) {
        for (int j = i+1; j < n; j++)
            a[i][n] = (a[i][n] - a[i][j] * a[j][n] % MOD + MOD) % MOD;
        a[i][n] = a[i][n] * modInv(a[i][i]) % MOD;
    }
    return true;
}

// 3. 行列式（模意义下）
ll determinant(vector<vector<ll>> a, int n) {
    ll det = 1;
    for (int i = 0; i < n; i++) {
        int pivot = i;
        for (int j = i+1; j < n; j++)
            if (a[j][i] > a[pivot][i]) pivot = j;
        if (pivot != i) { swap(a[i], a[pivot]); det = (MOD - det) % MOD; }
        if (a[i][i] == 0) return 0;
        det = det * a[i][i] % MOD;
        ll inv = modInv(a[i][i]);
        for (int j = i+1; j < n; j++) {
            ll f = a[j][i] * inv % MOD;
            for (int k = i; k < n; k++)
                a[j][k] = (a[j][k] - f * a[i][k] % MOD + MOD) % MOD;
        }
    }
    return det;
}

int main() {
    // 解方程组：2x+y=5, x+3y=10 → x=1, y=3
    vector<vector<double>> a = {{2,1,5},{1,3,10}};
    gaussJordan(a, 2);
    cout << "浮点解: x=" << a[0][2] << ", y=" << a[1][2] << endl;

    // 模意义下解同样方程组
    vector<vector<ll>> b = {{2,1,5},{1,3,10}};
    gaussMod(b, 2);
    cout << "模解: x=" << b[0][2] << ", y=" << b[1][2] << endl;

    // 行列式 |[2,1],[1,3]| = 5
    vector<vector<ll>> m = {{2,1},{1,3}};
    cout << "det = " << determinant(m, 2) << endl;
    return 0;
}

