## 核心思想

普通 BST 在数据有序时退化为链表（$O(n)$）。**平衡树**通过旋转维持树高 $O(\log n)$，保证所有操作均摊对数复杂度。

竞赛中最常用两种：
- **Treap**（Tree + Heap）：每个节点随机赋优先级，按堆性质旋转维持平衡，实现简单。
- **Splay**：每次操作后把节点旋转到根（splay 操作），均摊 $O(\log n)$，支持区间操作。

```mermaid
graph TD
  R["根 (优先级最大)"] --> L["左子树"]
  R --> R2["右子树"]
  L --> L1["..."]
  L --> L2["..."]
  style R fill:#91d5ff
```

## 一、Treap 实现

每个节点：键值 key、优先级 pri（随机）、左右儿子、子树大小 cnt。

**旋转**：
- 右旋（zig）：左儿子提到根，根变成右儿子。
- 左旋（zag）：右儿子提到根，根变成左儿子。

```cpp
struct Node {
    int key, pri, sz, cnt;
    int l, r;
} tr[N];
int tot, root;

int newNode(int key) {
    tr[++tot] = {key, rand(), 1, 1, 0, 0};
    return tot;
}

void pushUp(int u) {
    tr[u].sz = tr[tr[u].l].sz + tr[tr[u].r].sz + tr[u].cnt;
}

// 右旋：左儿子变根
void zig(int &u) {
    int v = tr[u].l;
    tr[u].l = tr[v].r;
    tr[v].r = u;
    u = v;
    pushUp(tr[u].r); pushUp(u);
}

// 左旋：右儿子变根
void zag(int &u) {
    int v = tr[u].r;
    tr[u].r = tr[v].l;
    tr[v].l = u;
    u = v;
    pushUp(tr[u].l); pushUp(u);
}
```

**插入**：递归插入，若子节点优先级更高则旋转。

```cpp
void insert(int &u, int key) {
    if (!u) { u = newNode(key); return; }
    if (tr[u].key == key) { tr[u].cnt++; pushUp(u); return; }
    if (key < tr[u].key) {
        insert(tr[u].l, key);
        if (tr[tr[u].l].pri > tr[u].pri) zig(u);
    } else {
        insert(tr[u].r, key);
        if (tr[tr[u].r].pri > tr[u].pri) zag(u);
    }
    pushUp(u);
}
```

**删除**：递归找到目标，若有两个儿子则把优先级高的旋上来，直到目标变成叶子再删。

```cpp
void remove(int &u, int key) {
    if (!u) return;
    if (tr[u].key == key) {
        if (tr[u].cnt > 1) { tr[u].cnt--; pushUp(u); return; }
        if (!tr[u].l || !tr[u].r) { u = tr[u].l | tr[u].r; return; }
        if (tr[tr[u].l].pri > tr[tr[u].r].pri) { zig(u); remove(tr[u].r, key); }
        else { zag(u); remove(tr[u].l, key); }
    } else if (key < tr[u].key) remove(tr[u].l, key);
    else remove(tr[u].r, key);
    pushUp(u);
}
```

## 二、Treap 常用查询

```cpp
// 排名（比 key 小的数的个数 + 1）
int getRank(int u, int key) {
    if (!u) return 1;
    if (tr[u].key == key) return tr[tr[u].l].sz + 1;
    if (key < tr[u].key) return getRank(tr[u].l, key);
    return tr[tr[u].l].sz + tr[u].cnt + getRank(tr[u].r, key);
}

// 第 k 大
int kth(int u, int k) {
    if (!u) return 0;
    if (k <= tr[tr[u].l].sz) return kth(tr[u].l, k);
    if (k <= tr[tr[u].l].sz + tr[u].cnt) return tr[u].key;
    return kth(tr[u].r, k - tr[tr[u].l].sz - tr[u].cnt);
}

// 前驱（小于 key 的最大值）
int pre(int u, int key) {
    if (!u) return -INF;
    if (tr[u].key >= key) return pre(tr[u].l, key);
    return max(tr[u].key, pre(tr[u].r, key));
}

// 后继（大于 key 的最小值）
int nxt(int u, int key) {
    if (!u) return INF;
    if (tr[u].key <= key) return nxt(tr[u].r, key);
    return min(tr[u].key, nxt(tr[u].l, key));
}
```

## 三、Splay 核心操作

Splay 通过 splay(u) 把节点 u 旋转到根：
- 若 u 是根的儿子：单旋（zig/zag）。
- 若 u 和父亲同在左侧/右侧：先旋父亲再旋 u（zig-zig / zag-zag）。
- 若 u 和父亲在不同侧：旋 u 两次（zig-zag / zag-zig）。

均摊复杂度 $O(\log n)$，证明用势能分析。

Splay 的优势：支持**区间操作**——把 l-1 splay 到根，r+1 splay 到根的右儿子，此时 r+1 的左子树就是区间 [l,r]，可以直接打懒标记。

## 四、平衡树的应用

1. **动态有序集合**：插入/删除/排名/第k大/前驱后继。
2. **区间翻转/区间加**：Splay 或 FHQ Treap（无旋 Treap）支持 split/merge。
3. **中位数维护**：对顶堆或平衡树。
4. **动态逆序对**：插入时查询排名。

## 五、FHQ Treap（无旋 Treap，推荐）

用 split 和 merge 代替旋转，实现更简洁，支持区间操作：

```cpp
// 按 key 分裂：左树 <= key，右树 > key
void split(int u, int key, int &x, int &y) {
    if (!u) { x = y = 0; return; }
    if (tr[u].key <= key) { x = u; split(tr[u].r, key, tr[u].r, y); }
    else { y = u; split(tr[u].l, key, x, tr[u].l); }
    pushUp(u);
}

// 合并：保证 x 所有 key < y 所有 key
int merge(int x, int y) {
    if (!x || !y) return x | y;
    if (tr[x].pri > tr[y].pri) { tr[x].r = merge(tr[x].r, y); pushUp(x); return x; }
    else { tr[y].l = merge(x, tr[y].l); pushUp(y); return y; }
}
```

插入：split(root, key, x, z); split(x, key-1, x, y); y 处加节点; root = merge(merge(x,y), z)。

## 复杂度

| 操作 | Treap | Splay | FHQ Treap |
|---|---|---|---|
| 插入 | $O(\log n)$ 期望 | $O(\log n)$ 均摊 | $O(\log n)$ 期望 |
| 删除 | $O(\log n)$ 期望 | $O(\log n)$ 均摊 | $O(\log n)$ 期望 |
| 排名/第k大 | $O(\log n)$ | $O(\log n)$ | $O(\log n)$ |
| 区间操作 | 不支持 | 支持 | 支持 |

## 常见应用

1. CCPC：动态有序集合、区间翻转、中位数。
2. 蓝桥杯：简单平衡树操作（Treap 即可）。
3. 与其他结构结合：平衡树套线段树、Splay 维护序列。

data.templateCode:
#include <bits/stdc++.h>
using namespace std;
const int N = 1e5 + 5, INF = 1e9;

// FHQ Treap（无旋 Treap）模板
struct Node {
    int key, pri, sz, cnt, l, r;
} tr[N];
int tot, root;

int newNode(int key) {
    tr[++tot] = {key, rand(), 1, 1, 0, 0};
    return tot;
}

void pushUp(int u) {
    tr[u].sz = tr[tr[u].l].sz + tr[tr[u].r].sz + tr[u].cnt;
}

void split(int u, int key, int &x, int &y) {
    if (!u) { x = y = 0; return; }
    if (tr[u].key <= key) {
        x = u;
        split(tr[u].r, key, tr[u].r, y);
    } else {
        y = u;
        split(tr[u].l, key, x, tr[u].l);
    }
    pushUp(u);
}

int merge(int x, int y) {
    if (!x || !y) return x | y;
    if (tr[x].pri > tr[y].pri) {
        tr[x].r = merge(tr[x].r, y);
        pushUp(x);
        return x;
    } else {
        tr[y].l = merge(x, tr[y].l);
        pushUp(y);
        return y;
    }
}

void insert(int key) {
    int x, y, z;
    split(root, key, x, z);
    split(x, key - 1, x, y);
    if (y) tr[y].cnt++, pushUp(y);
    else y = newNode(key);
    root = merge(merge(x, y), z);
}

void remove(int key) {
    int x, y, z;
    split(root, key, x, z);
    split(x, key - 1, x, y);
    if (y && tr[y].cnt > 1) tr[y].cnt--, pushUp(y);
    else y = 0;
    root = merge(merge(x, y), z);
}

int getRank(int key) {
    int x, y;
    split(root, key - 1, x, y);
    int r = tr[x].sz + 1;
    root = merge(x, y);
    return r;
}

int kth(int u, int k) {
    if (!u) return 0;
    if (k <= tr[tr[u].l].sz) return kth(tr[u].l, k);
    if (k <= tr[tr[u].l].sz + tr[u].cnt) return tr[u].key;
    return kth(tr[u].r, k - tr[tr[u].l].sz - tr[u].cnt);
}

int pre(int key) {
    int x, y;
    split(root, key - 1, x, y);
    int u = x;
    while (tr[u].r) u = tr[u].r;
    int r = u ? tr[u].key : -INF;
    root = merge(x, y);
    return r;
}

int nxt(int key) {
    int x, y;
    split(root, key, x, y);
    int u = y;
    while (tr[u].l) u = tr[u].l;
    int r = u ? tr[u].key : INF;
    root = merge(x, y);
    return r;
}

int main() {
    srand(12345);
    insert(5); insert(3); insert(7); insert(3); insert(9);
    cout << "rank(5) = " << getRank(5) << endl;  // 3 (3,3,5)
    cout << "kth(3) = " << kth(root, 3) << endl;  // 5
    cout << "pre(6) = " << pre(6) << endl;  // 5
    cout << "nxt(6) = " << nxt(6) << endl;  // 7
    remove(3);
    cout << "after remove 3, rank(5) = " << getRank(5) << endl;  // 2
    return 0;
}

