#include <bits/stdc++.h>
using namespace std;
const int N = 1e5 + 5, INF = 1e9;

vector<int> adj[N];
int fa[N], dep[N], sz[N], son[N];
int top[N], dfn[N], rnk[N], timer;
int val[N], n;

// 线段树（区间加 + 区间最大值查询，示例）
struct SegTree {
    int mx[N*4], tag[N*4];
    void build(int u, int l, int r) {
        if (l == r) { mx[u] = val[rnk[l]]; return; }
        int mid = (l+r)/2;
        build(u*2, l, mid); build(u*2+1, mid+1, r);
        mx[u] = max(mx[u*2], mx[u*2+1]);
    }
    void pushDown(int u) {
        if (tag[u]) {
            mx[u*2] += tag[u]; tag[u*2] += tag[u];
            mx[u*2+1] += tag[u]; tag[u*2+1] += tag[u];
            tag[u] = 0;
        }
    }
    void update(int u, int l, int r, int ql, int qr, int w) {
        if (ql <= l && r <= qr) { mx[u] += w; tag[u] += w; return; }
        pushDown(u);
        int mid = (l+r)/2;
        if (ql <= mid) update(u*2, l, mid, ql, qr, w);
        if (qr > mid) update(u*2+1, mid+1, r, ql, qr, w);
        mx[u] = max(mx[u*2], mx[u*2+1]);
    }
    int query(int u, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) return mx[u];
        pushDown(u);
        int mid = (l+r)/2, res = -INF;
        if (ql <= mid) res = max(res, query(u*2, l, mid, ql, qr));
        if (qr > mid) res = max(res, query(u*2+1, mid+1, r, ql, qr));
        return res;
    }
} seg;

void dfs1(int u, int f) {
    fa[u] = f; dep[u] = dep[f] + 1; sz[u] = 1;
    int maxSz = 0;
    for (int v : adj[u]) {
        if (v == f) continue;
        dfs1(v, u);
        sz[u] += sz[v];
        if (sz[v] > maxSz) { maxSz = sz[v]; son[u] = v; }
    }
}

void dfs2(int u, int t) {
    top[u] = t;
    dfn[u] = ++timer;
    rnk[timer] = u;
    if (son[u]) dfs2(son[u], t);
    for (int v : adj[u]) {
        if (v == fa[u] || v == son[u]) continue;
        dfs2(v, v);
    }
}

int queryPath(int u, int v) {
    int res = -INF;
    while (top[u] != top[v]) {
        if (dep[top[u]] < dep[top[v]]) swap(u, v);
        res = max(res, seg.query(1, 1, n, dfn[top[u]], dfn[u]));
        u = fa[top[u]];
    }
    if (dep[u] > dep[v]) swap(u, v);
    res = max(res, seg.query(1, 1, n, dfn[u], dfn[v]));
    return res;
}

void updatePath(int u, int v, int w) {
    while (top[u] != top[v]) {
        if (dep[top[u]] < dep[top[v]]) swap(u, v);
        seg.update(1, 1, n, dfn[top[u]], dfn[u], w);
        u = fa[top[u]];
    }
    if (dep[u] > dep[v]) swap(u, v);
    seg.update(1, 1, n, dfn[u], dfn[v], w);
}

int lca(int u, int v) {
    while (top[u] != top[v]) {
        if (dep[top[u]] < dep[top[v]]) swap(u, v);
        u = fa[top[u]];
    }
    return dep[u] < dep[v] ? u : v;
}

int main() {
    // 示例：7 个节点的树
    n = 7;
    int edges[6][2] = {{1,2},{1,3},{2,4},{2,5},{3,6},{3,7}};
    for (auto& [u,v] : edges) { adj[u].push_back(v); adj[v].push_back(u); }
    for (int i = 1; i <= n; i++) val[i] = i;  // 权值 = 编号
    dfs1(1, 0);
    dfs2(1, 1);
    seg.build(1, 1, n);
    cout << "LCA(4,6) = " << lca(4,6) << endl;  // 1
    cout << "path max(4,6) = " << queryPath(4,6) << endl;  // max(4,2,1,3,6)=6
    updatePath(4, 6, 10);  // 路径上所有点 +10
    cout << "after +10, path max(4,6) = " << queryPath(4,6) << endl;  // 16
    return 0;
}

