#include <bits/stdc++.h>
using namespace std;
const int N = 5005, INF = 1e9;

struct Edge {
    int to, cap, cost, rev;
};
vector<Edge> g[N];
int h[N], dist[N], prevv[N], preve[N];

void addEdge(int from, int to, int cap, int cost) {
    g[from].push_back({to, cap, cost, (int)g[to].size()});
    g[to].push_back({from, 0, -cost, (int)g[from].size() - 1});
}

bool dijkstra(int s, int t, int n) {
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;
    fill(dist, dist + n + 1, INF);
    dist[s] = 0; pq.push({0, s});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (dist[u] < d) continue;
        for (int i = 0; i < (int)g[u].size(); i++) {
            Edge &e = g[u][i];
            int nc = e.cost + h[u] - h[e.to];
            if (e.cap > 0 && dist[e.to] > d + nc) {
                dist[e.to] = d + nc;
                prevv[e.to] = u; preve[e.to] = i;
                pq.push({dist[e.to], e.to});
            }
        }
    }
    return dist[t] < INF;
}

pair<int,int> minCostFlow(int s, int t, int n) {
    int flow = 0, cost = 0;
    fill(h, h + n + 1, 0);
    while (dijkstra(s, t, n)) {
        for (int v = 1; v <= n; v++) if (dist[v] < INF) h[v] += dist[v];
        int d = INF;
        for (int v = t; v != s; v = prevv[v])
            d = min(d, g[prevv[v]][preve[v]].cap);
        flow += d;
        cost += d * h[t];
        for (int v = t; v != s; v = prevv[v]) {
            Edge &e = g[prevv[v]][preve[v]];
            e.cap -= d;
            g[v][e.rev].cap += d;
        }
    }
    return {flow, cost};
}

int main() {
    // 示例：S=1, A=2, B=3, T=4
    // S->A cap3 cost2, S->B cap2 cost5, A->T cap4 cost1, B->T cap2 cost3
    addEdge(1, 2, 3, 2);
    addEdge(1, 3, 2, 5);
    addEdge(2, 4, 4, 1);
    addEdge(3, 4, 2, 3);
    auto [flow, cost] = minCostFlow(1, 4, 4);
    cout << "最大流 = " << flow << endl;  // 5 (3+2)
    cout << "最小费用 = " << cost << endl;  // 3*2+2*1 + 2*5+2*3 = 8+16=24? 
    // 实际：A路径3*2+3*1=9, B路径2*5+2*3=16, 总25
    return 0;
}

