#include <bits/stdc++.h>
using namespace std;

struct TwoSAT {
    int n;
    vector<vector<int>> g;
    vector<int> dfn, low, scc, stk;
    int timer, sccCnt, top;
    vector<bool> inStk;

    TwoSAT(int n) : n(n), g(2*n), dfn(2*n,0), low(2*n,0), scc(2*n,0), stk(2*n), inStk(2*n,false), timer(0), sccCnt(0), top(0) {}

    // 变量 i 的真节点 = 2*i, 假节点 = 2*i+1
    void addClause(int i, bool iv, int j, bool jv) {
        int u = 2*i + (iv ? 0 : 1);  // i=iv 为真
        int v = 2*j + (jv ? 0 : 1);
        g[u^1].push_back(v);  // ¬u => v
        g[v^1].push_back(u);  // ¬v => u
    }

    void tarjan(int u) {
        dfn[u] = low[u] = ++timer;
        stk[top++] = u; inStk[u] = true;
        for (int v : g[u]) {
            if (!dfn[v]) { tarjan(v); low[u] = min(low[u], low[v]); }
            else if (inStk[v]) low[u] = min(low[u], dfn[v]);
        }
        if (dfn[u] == low[u]) {
            sccCnt++;
            while (true) {
                int v = stk[--top]; inStk[v] = false; scc[v] = sccCnt;
                if (v == u) break;
            }
        }
    }

    bool solve() {
        for (int i = 0; i < 2*n; i++) if (!dfn[i]) tarjan(i);
        for (int i = 0; i < n; i++)
            if (scc[2*i] == scc[2*i+1]) return false;
        return true;
    }

    bool getValue(int i) {
        return scc[2*i] > scc[2*i+1];
    }
};

int main() {
    // 示例：3 个变量，约束：
    // x0 ∨ x1 (0或1至少一个真)
    // ¬x1 ∨ x2 (1假或2真)
    // x0 ∨ ¬x2 (0真或2假)
    TwoSAT ts(3);
    ts.addClause(0, true, 1, true);   // x0 ∨ x1
    ts.addClause(1, false, 2, true);  // ¬x1 ∨ x2
    ts.addClause(0, true, 2, false);  // x0 ∨ ¬x2

    if (ts.solve()) {
        cout << "有解，赋值：" << endl;
        for (int i = 0; i < 3; i++)
            cout << "x" << i << " = " << (ts.getValue(i) ? "真" : "假") << endl;
    } else {
        cout << "无解" << endl;
    }

    // 矛盾示例：x0 ∨ x0 且 ¬x0 ∨ ¬x0（x0必须真且必须假）
    TwoSAT ts2(1);
    ts2.addClause(0, true, 0, true);
    ts2.addClause(0, false, 0, false);
    cout << "矛盾示例: " << (ts2.solve() ? "有解" : "无解") << endl;
    return 0;
}

