## 核心思想

后缀自动机（Suffix Automaton, SAM）是一个**有向无环图（DAG）**，能在线性时间和空间内表示字符串的**所有子串**。它是处理字符串子串问题的最强工具之一。

SAM 的每个状态（节点）代表一个**endpos 等价类**：所有 endpos 集合相同的子串归为一个状态。

**endpos(s)**：子串 s 在原串中所有出现位置的右端点集合。

性质：
- 两个子串的 endpos 要么相同，要么一个包含另一个（不会部分相交）。
- 同一状态的子串长度构成连续区间 [minlen, maxlen]。
- 后缀链接（link）构成一棵树（parent tree），link[u] 指向 u 的 endpos 集合的最小超集状态。

```mermaid
graph TD
  S["初始状态<br/>len=0"] -->|a| A["状态1<br/>len=1"]
  A -->|b| B["状态2<br/>len=2"]
  B -->|a| C["状态3<br/>len=3"]
  A -.->|link| S
  B -.->|link| S
  C -.->|link| A
  style S fill:#91d5ff
```

## 一、SAM 的构建（在线算法）

每个状态维护：
- `len`：该状态最长子串的长度
- `link`：后缀链接
- `next[c]`：转移边

```cpp
struct State {
    int len, link;
    int next[26];
} st[N*2];
int sz, last;

void samInit() {
    st[0].len = 0; st[0].link = -1;
    memset(st[0].next, -1, sizeof st[0].next);
    sz = 1; last = 0;
}

void samExtend(int c) {
    int cur = sz++;
    st[cur].len = st[last].len + 1;
    memset(st[cur].next, -1, sizeof st[cur].next);
    int p = last;
    while (p != -1 && st[p].next[c] == -1) {
        st[p].next[c] = cur;
        p = st[p].link;
    }
    if (p == -1) {
        st[cur].link = 0;
    } else {
        int q = st[p].next[c];
        if (st[p].len + 1 == st[q].len) {
            st[cur].link = q;
        } else {
            int clone = sz++;
            st[clone].len = st[p].len + 1;
            memcpy(st[clone].next, st[q].next, sizeof st[q].next);
            st[clone].link = st[q].link;
            while (p != -1 && st[p].next[c] == q) {
                st[p].next[c] = clone;
                p = st[p].link;
            }
            st[q].link = st[cur].link = clone;
        }
    }
    last = cur;
}
```

构建复杂度 $O(n)$（字符集常数），状态数不超过 $2n-1$。

## 二、SAM 的核心应用

### 1. 不同子串个数

每个状态 u 贡献 `st[u].len - st[st[u].link].len` 个不同子串（该状态的子串长度区间内的数量）。

```cpp
long long countSubstrings() {
    long long ans = 0;
    for (int i = 1; i < sz; i++)
        ans += st[i].len - st[st[i].link].len;
    return ans;
}
```

### 2. 子串出现次数

每个状态的出现次数 = 该状态 endpos 集合大小。构建时每个前缀对应的状态（cur）cnt=1，然后按 len 从大到小（拓扑序）把 cnt 累加到 link。

```cpp
int cnt[N*2];
// 构建时：cnt[cur] = 1（每个前缀状态）
// 构建后按 len 降序排序（桶排序），累加：
for (int i = sz-1; i >= 0; i--) cnt[st[ord[i]].link] += cnt[ord[i]];
// 查询子串 s 的出现次数：从初始状态沿 s 走，到达状态 u，cnt[u] 即出现次数
```

### 3. 最长公共子串（两个字符串）

对串 A 建 SAM，用串 B 在 SAM 上跑：维护当前状态 u 和当前匹配长度 l。每读一个字符 c：
- 若 u 有 c 转移，u = next[c], l++。
- 否则沿 link 跳，直到找到有 c 转移的状态或到根，更新 l。
- 全过程记录最大 l。

```cpp
int longestCommonSubstring(const string& t) {
    int u = 0, l = 0, ans = 0;
    for (char ch : t) {
        int c = ch - 'a';
        while (u && st[u].next[c] == -1) { u = st[u].link; l = st[u].len; }
        if (st[u].next[c] != -1) { u = st[u].next[c]; l++; }
        else { u = 0; l = 0; }
        ans = max(ans, l);
    }
    return ans;
}
```

### 4. 第 k 小子串

在 SAM 的 DAG 上 DP 求每个状态出发的子串数，然后按字典序走。

## 三、SAM vs 后缀树 vs 后缀数组

| 数据结构 | 空间 | 构建时间 | 子串查询 |
|---|---|---|---|
| 后缀数组 | O(n) | O(n log n) | 需二分 + LCP |
| 后缀树 | O(n) | O(n)（Ukkonen） | 直接走 |
| SAM | O(n) | O(n) | 直接走，功能更强 |

SAM 是后缀树的"压缩"表示，状态数更少，功能等价或更强。

## 四、复杂度

- 构建：$O(n · |\Sigma|)$（|\Sigma| 为字符集大小，常数）
- 空间：$O(n)$ 状态，$O(n · |\Sigma|)$ 转移
- 各类查询：$O(n)$ 或 $O(查询串长)$

## 常见应用

1. CCPC：不同子串数、子串出现次数、最长公共子串、第 k 小子串。
2. 蓝桥杯：简单子串计数（SAM 入门）。
3. 与其他结构结合：SAM + 线段树、SAM + 启发式合并。

data.templateCode:
#include <bits/stdc++.h>
using namespace std;
const int N = 1e5 + 5;

struct State {
    int len, link;
    int next[26];
} st[N*2];
int sz, last;
int cnt[N*2];

void samInit() {
    st[0].len = 0; st[0].link = -1;
    memset(st[0].next, -1, sizeof st[0].next);
    sz = 1; last = 0;
}

void samExtend(int c) {
    int cur = sz++;
    st[cur].len = st[last].len + 1;
    memset(st[cur].next, -1, sizeof st[cur].next);
    cnt[cur] = 1;
    int p = last;
    while (p != -1 && st[p].next[c] == -1) {
        st[p].next[c] = cur;
        p = st[p].link;
    }
    if (p == -1) st[cur].link = 0;
    else {
        int q = st[p].next[c];
        if (st[p].len + 1 == st[q].len) st[cur].link = q;
        else {
            int clone = sz++;
            st[clone].len = st[p].len + 1;
            memcpy(st[clone].next, st[q].next, sizeof st[q].next);
            st[clone].link = st[q].link;
            while (p != -1 && st[p].next[c] == q) {
                st[p].next[c] = clone;
                p = st[p].link;
            }
            st[q].link = st[cur].link = clone;
        }
    }
    last = cur;
}

// 不同子串个数
long long countSubstrings() {
    long long ans = 0;
    for (int i = 1; i < sz; i++)
        ans += st[i].len - st[st[i].link].len;
    return ans;
}

// 按 len 桶排序，累加出现次数
int ord[N*2], bucket[N];
void buildCnt(int n) {
    memset(bucket, 0, sizeof bucket);
    for (int i = 0; i < sz; i++) bucket[st[i].len]++;
    for (int i = 1; i <= n; i++) bucket[i] += bucket[i-1];
    for (int i = sz-1; i >= 0; i--) ord[--bucket[st[i].len]] = i;
    for (int i = sz-1; i >= 1; i--)
        cnt[st[ord[i]].link] += cnt[ord[i]];
}

// 查询子串出现次数
int countOccurrences(const string& s) {
    int u = 0;
    for (char ch : s) {
        int c = ch - 'a';
        if (st[u].next[c] == -1) return 0;
        u = st[u].next[c];
    }
    return cnt[u];
}

// 最长公共子串
int longestCommonSubstring(const string& t) {
    int u = 0, l = 0, ans = 0;
    for (char ch : t) {
        int c = ch - 'a';
        while (u && st[u].next[c] == -1) { u = st[u].link; l = st[u].len; }
        if (st[u].next[c] != -1) { u = st[u].next[c]; l++; }
        else { u = 0; l = 0; }
        ans = max(ans, l);
    }
    return ans;
}

int main() {
    string s = "ababa";
    samInit();
    for (char ch : s) samExtend(ch - 'a');
    buildCnt(s.size());

    cout << "不同子串个数 = " << countSubstrings() << endl;  // 9 (a,b,ab,ba,aba,bab,abab,baba,ababa)
    cout << "'aba' 出现次数 = " << countOccurrences("aba") << endl;  // 2
    cout << "'ab' 出现次数 = " << countOccurrences("ab") << endl;   // 2
    cout << "与 'babab' 的最长公共子串 = " << longestCommonSubstring("babab") << endl;  // 4
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Manacher {
    string t;
    vector<int> p;
    int n;

    void init(const string& s) {
        t = "^#";
        for (char c : s) { t += c; t += '#'; }
        t += '$';
        n = t.size();
        p.assign(n, 0);
        int mid = 0, r = 0;
        for (int i = 1; i < n - 1; i++) {
            if (i < r) p[i] = min(p[2*mid - i], r - i);
            else p[i] = 1;
            while (t[i + p[i]] == t[i - p[i]]) p[i]++;
            if (i + p[i] > r) { mid = i; r = i + p[i]; }
        }
    }

    // 最长回文子串
    string longestPalindrome(const string& s) {
        int maxLen = 0, center = 0;
        for (int i = 1; i < n - 1; i++) {
            if (p[i] - 1 > maxLen) { maxLen = p[i] - 1; center = i; }
        }
        return s.substr((center - maxLen) / 2, maxLen);
    }

    // 原串 [l,r] 是否回文（0-indexed）
    bool isPalindrome(int l, int r) {
        // 预处理后中心位置 = l+r+2，半径需要 >= r-l+2
        int center = l + r + 2;
        return p[center] - 1 >= r - l + 1;
    }

    // 回文子串总数
    long long countPalindromes() {
        long long ans = 0;
        for (int i = 1; i < n - 1; i++)
            ans += (p[i]) / 2;  // p[i]-1 长度，回文数 = ceil((p[i]-1)/2) = p[i]/2
        return ans;
    }
};

int main() {
    string s = "ababa";
    Manacher m;
    m.init(s);
    cout << "最长回文子串: " << m.longestPalindrome(s) << endl;  // ababa
    cout << "s[0..4] 是否回文: " << m.isPalindrome(0, 4) << endl;  // 1
    cout << "s[0..2] 是否回文: " << m.isPalindrome(0, 2) << endl;  // 1 (aba)
    cout << "s[1..3] 是否回文: " << m.isPalindrome(1, 3) << endl;  // 1 (bab)
    cout << "回文子串总数: " << m.countPalindromes() << endl;  // a,b,a,b,a,aba,bab,ababa = 8? 实际9
    return 0;
}

