#include <bits/stdc++.h>
using namespace std;
const int N = 5e4 + 5, INF = 1e9;

// 1. 斜率优化：玩具装箱（P3195）
// dp[i] = min(dp[j] + (sum[i]-sum[j]+i-j-1-L)^2)
// 令 a[i] = sum[i]+i, b[j] = sum[j]+j+1+L
// dp[i] = min(dp[j] + (a[i]-b[j])^2) = min(dp[j]+b[j]^2 - 2*a[i]*b[j]) + a[i]^2
// 点 (b[j], dp[j]+b[j]^2)，斜率 2*a[i]
long long dp[N], sum[N], a[N], b[N];
int q[N];

double slope(int i, int j) {
    return (double)(b[j]*b[j]+dp[j] - b[i]*b[i]-dp[i]) / (b[j] - b[i]);
}

void slopeOpt(int n, int L) {
    int head = 1, tail = 1;
    q[1] = 0;
    for (int i = 1; i <= n; i++) {
        a[i] = sum[i] + i;
        b[i] = sum[i] + i + 1 + L;
        while (head < tail && slope(q[head], q[head+1]) <= 2.0 * a[i]) head++;
        int j = q[head];
        dp[i] = dp[j] + (a[i] - b[j]) * (a[i] - b[j]);
        while (head < tail && slope(q[tail-1], q[tail]) >= slope(q[tail], i)) tail--;
        q[++tail] = i;
    }
}

// 2. 单调队列优化：滑动窗口最大值
vector<int> slidingWindowMax(vector<int>& a, int k) {
    vector<int> ans;
    deque<int> dq;
    for (int i = 0; i < (int)a.size(); i++) {
        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();
        dq.push_back(i);
        while (dq.front() <= i - k) dq.pop_front();
        if (i >= k - 1) ans.push_back(a[dq.front()]);
    }
    return ans;
}

// 3. 四边形不等式优化：石子合并（环形，简化版线性）
int dp2[N][N], opt[N][N], w2[N][N];
void quadOpt(int n) {
    for (int i = 1; i <= n; i++) { dp2[i][i] = 0; opt[i][i] = i; }
    for (int len = 2; len <= n; len++) {
        for (int l = 1; l + len - 1 <= n; l++) {
            int r = l + len - 1;
            dp2[l][r] = INF;
            for (int k = opt[l][r-1]; k <= opt[l+1][r]; k++) {
                int val = dp2[l][k] + dp2[k+1][r] + w2[l][r];
                if (val < dp2[l][r]) { dp2[l][r] = val; opt[l][r] = k; }
            }
        }
    }
}

int main() {
    // 斜率优化示例
    int n = 5, L = 4;
    int c[] = {0, 1, 2, 3, 4, 5};
    for (int i = 1; i <= n; i++) sum[i] = sum[i-1] + c[i];
    slopeOpt(n, L);
    cout << "玩具装箱 dp[n] = " << dp[n] << endl;

    // 单调队列示例
    vector<int> a = {1,3,-1,-3,5,3,6,7};
    auto res = slidingWindowMax(a, 3);
    cout << "滑动窗口最大值: ";
    for (int x : res) cout << x << " ";
    cout << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// 1. 分组背包（P1757 模板）
int groupKnapsack(vector<vector<pair<int,int>>>& groups, int C) {
    vector<int> dp(C + 1, 0);
    for (auto& g : groups) {                 // 组
        for (int j = C; j >= 0; j--) {       // 容量倒序
            for (auto& [w, v] : g) {
                if (j >= w) dp[j] = max(dp[j], dp[j - w] + v);
            }
        }
    }
    return dp[C];
}

// 2. 混合背包：w/v/s 数组，s=1 为 01，s>1 为多重，s=-1 为完全
int mixedKnapsack(vector<int>& w, vector<int>& v, vector<int>& s, int C) {
    vector<int> dp(C + 1, 0);
    for (int i = 0; i < (int)w.size(); i++) {
        if (s[i] == -1) {                    // 完全：正序
            for (int j = w[i]; j <= C; j++)
                dp[j] = max(dp[j], dp[j - w[i]] + v[i]);
        } else {                             // 01 / 多重：二进制拆成 01 倒序
            int cnt = s[i], k = 1;
            while (k <= cnt) {
                for (int j = C; j >= w[i] * k; j--)
                    dp[j] = max(dp[j], dp[j - w[i] * k] + v[i] * k);
                cnt -= k; k <<= 1;
            }
            if (cnt > 0)
                for (int j = C; j >= w[i] * cnt; j--)
                    dp[j] = max(dp[j], dp[j - w[i] * cnt] + v[i] * cnt);
        }
    }
    return dp[C];
}

// 3. 恰好装满：dp[0]=0，其余 -INF
int exactlyFill(vector<int>& w, vector<int>& v, int C) {
    const int NEG = -1e9;
    vector<int> dp(C + 1, NEG);
    dp[0] = 0;
    for (int i = 0; i < (int)w.size(); i++)
        for (int j = C; j >= w[i]; j--)
            dp[j] = max(dp[j], dp[j - w[i]] + v[i]);
    return dp[C] < 0 ? -1 : dp[C];           // -1 表示无法恰好装满
}

// 4. 方案计数（01 背包）：mod 取模
int countWays(vector<int>& w, int C) {
    const int MOD = 1e9 + 7;
    vector<int> dp(C + 1, 0);
    dp[0] = 1;
    for (int i = 0; i < (int)w.size(); i++)
        for (int j = C; j >= w[i]; j--)
            dp[j] = (dp[j] + dp[j - w[i]]) % MOD;
    return dp[C];
}

