#include <bits/stdc++.h>
using namespace std;

// 1. 最长公共子序列 LCS
int lcs(const string& a, const string& b) {
    int n = a.size(), m = b.size();
    vector<int> dp(m + 1, 0), pre(m + 1, 0);
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (a[i-1] == b[j-1]) dp[j] = pre[j-1] + 1;
            else dp[j] = max(dp[j-1], pre[j]);
        }
        swap(dp, pre);
        fill(dp.begin(), dp.end(), 0);
    }
    return pre[m];
}

// 2. 编辑距离（力扣 72）
int editDistance(string a, string b) {
    int n = a.size(), m = b.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1));
    for (int i = 0; i <= n; i++) dp[i][0] = i;
    for (int j = 0; j <= m; j++) dp[0][j] = j;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            dp[i][j] = min({dp[i-1][j] + 1,
                            dp[i][j-1] + 1,
                            dp[i-1][j-1] + (a[i-1] != b[j-1])});
    return dp[n][m];
}

// 3. 最长公共上升子序列 LCIS（O(nm)）
int lcis(const vector<int>& a, const vector<int>& b) {
    int n = a.size(), m = b.size();
    vector<int> dp(m + 1, 0);
    for (int i = 1; i <= n; i++) {
        int mx = 0;
        for (int j = 1; j <= m; j++) {
            if (a[i-1] == b[j-1]) dp[j] = max(dp[j], mx + 1);
            if (b[j-1] < a[i-1]) mx = max(mx, dp[j]);
        }
    }
    return *max_element(dp.begin(), dp.end());
}

int main() {
    cout << lcs("abcde", "ace") << endl;       // 3
    cout << editDistance("horse", "ros") << endl; // 3
    cout << lcis({1,3,2,4}, {1,2,3,4}) << endl;  // 3: 1,2,4
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int MOD = 1e9 + 7;

// 1. 组合数递推（杨辉三角，n 小）
long long C[1005][1005];
void initComb(int n) {
    for (int i = 0; i <= n; i++) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; j++)
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
    }
}

// 2. 卡特兰数（递推，O(n^2)，n ≤ 5000）
long long catalan(int n) {
    vector<long long> h(n + 1);
    h[0] = 1;
    for (int i = 1; i <= n; i++)
        for (int j = 0; j < i; j++)
            h[i] = (h[i] + h[j] * h[i-1-j]) % MOD;
    return h[n];
}

// 3. 错排 D_n
long long derange(int n) {
    long long d0 = 1, d1 = 0;   // D_0=1（空排列）, D_1=0
    if (n == 0) return d0;
    for (int i = 2; i <= n; i++) {
        long long d2 = (i - 1) * (d0 + d1) % MOD;
        d0 = d1; d1 = d2;
    }
    return d1;
}

// 4. P1077 摆花：前 i 种花摆 j 盆（前缀和优化）
long long plantFlowers(vector<int>& a, int m) {
    int n = a.size();
    vector<long long> dp(m + 1, 0);
    dp[0] = 1;
    for (int i = 0; i < n; i++) {
        vector<long long> pre(m + 1);
        pre[0] = dp[0];
        for (int j = 1; j <= m; j++) pre[j] = (pre[j-1] + dp[j]) % MOD;
        vector<long long> ndp(m + 1, 0);
        for (int j = 0; j <= m; j++) {
            int l = max(0, j - a[i]);
            ndp[j] = (pre[j] - (l ? pre[l-1] : 0) + MOD) % MOD;
        }
        dp = ndp;
    }
    return dp[m];
}

#include <bits/stdc++.h>
using namespace std;

// 1. Nim 游戏：异或和判定（P2197）
bool nimWin(vector<int>& piles) {
    int x = 0;
    for (int p : piles) x ^= p;
    return x != 0;
}

// 2. SG 函数（记忆化）
int sg[10005];
int mex(int x, vector<int>& f) {
    if (sg[x] != -1) return sg[x];
    bool vis[10005] = {0};
    for (int k : f)
        if (x >= k) vis[mex(x - k, f)] = true;
    for (int i = 0; ; i++) if (!vis[i]) return sg[x] = i;
}

// 3. 简单取石子博弈 DP：一堆石子，每次取 f[] 中某数，取完者胜
// win[i] = 是否存在 k∈f 使 win[i-k] == false（到达必败态）
bool win[10005];
bool takeStone(int n, vector<int>& f) {
    win[0] = false;
    for (int i = 1; i <= n; i++) {
        win[i] = false;
        for (int k : f)
            if (i >= k && !win[i - k]) { win[i] = true; break; }
    }
    return win[n];
}

int main() {
    cout << "Nim {3,4,5} = " << nimWin({3,4,5}) << endl;  // 3^4^5=2 → 胜
    memset(sg, -1, sizeof sg);
    vector<int> f = {1, 2, 3};   // 每次可取 1/2/3
    cout << "SG(5) = " << mex(5, f) << endl;
    cout << "take(5) = " << takeStone(5, f) << endl;  // 5%4=1 → 胜
    return 0;
}

