#include <bits/stdc++.h>
using namespace std;

const int N = 305;
int n, m, val[N];
vector<int> son[N];
int dp[N][N];   // dp[u][j]: u 子树选 j 门（含 u）的最大学分

// 1. 树上背包（P2014 选课，含虚拟根 0）
void dfs(int u) {
    dp[u][1] = val[u];
    for (int v : son[u]) {
        dfs(v);
        for (int j = m; j >= 1; j--)
            for (int k = 1; k < j; k++)
                dp[u][j] = max(dp[u][j], dp[u][j-k] + dp[v][k]);
    }
}

// 2. 换根 DP：所有节点深度和（P3478）
int sz[N]; long long sum[N];
void dfs1(int u, int fa) {
    sz[u] = 1;
    for (int v : adj[u]) if (v != fa) {
        dfs1(v, u);
        sz[u] += sz[v];
        sum[u] += sum[v] + sz[v];
    }
}
void dfs2(int u, int fa) {
    for (int v : adj[u]) if (v != fa) {
        sum[v] = sum[u] - sz[v] + (n - sz[v]);
        dfs2(v, u);
    }
}

// 3. 基环树：找环（拓扑删叶）
int deg[N]; queue<int> q; bool inCycle[N];
void findCycle(int n) {
    for (int i = 1; i <= n; i++) if (deg[i] == 1) q.push(i);
    for (int i = 1; i <= n; i++) inCycle[i] = true;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inCycle[u] = false;
        for (int v : adj[u]) if (--deg[v] == 1) q.push(v);
    }
}

#include <bits/stdc++.h>
using namespace std;

// 1. DAG 最长路（拓扑序 DP）
int dagLongest(int n, vector<vector<int>>& adj, vector<int>& w) {
    vector<int> indeg(n + 1, 0), dp(n + 1, 0);
    for (int u = 1; u <= n; u++) for (int v : adj[u]) indeg[v]++;
    queue<int> q;
    for (int u = 1; u <= n; u++) if (indeg[u] == 0) q.push(u);
    int ans = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) {
            dp[v] = max(dp[v], dp[u] + w[v]);
            ans = max(ans, dp[v]);
            if (--indeg[v] == 0) q.push(v);
        }
    }
    return ans;
}

// 2. 最短路计数（Dijkstra + 计数）
const int MOD = 1e9 + 7;
vector<long long> dijkstraCount(int s, vector<vector<pair<int,int>>>& g) {
    int n = g.size() - 1;
    vector<long long> dist(n + 1, 1e18), cnt(n + 1, 0);
    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
    dist[s] = 0; cnt[s] = 1; pq.push({0, s});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d != dist[u]) continue;
        for (auto [v, w] : g[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                cnt[v] = cnt[u];
                pq.push({dist[v], v});
            } else if (dist[u] + w == dist[v]) {
                cnt[v] = (cnt[v] + cnt[u]) % MOD;
            }
        }
    }
    return cnt;  // cnt[v] = s 到 v 的最短路条数
}

// 3. SCC 缩点（Tarjan 找强连通分量，之后按分量建 DAG 做 DP）
// 此处仅列框架：tarjan 求出每个点所属 scc → 建新图 → 拓扑 DP

