#include <bits/stdc++.h>
using namespace std;
const int MOD = 1e9 + 7;
using Mat = vector<vector<long long>>;

Mat mul(const Mat& a, const Mat& b) {
    int n = a.size(), m = b[0].size(), k = a[0].size();
    Mat c(n, vector<long long>(m, 0));
    for (int i = 0; i < n; i++)
        for (int t = 0; t < k; t++) if (a[i][t])
            for (int j = 0; j < m; j++)
                c[i][j] = (c[i][j] + a[i][t] * b[t][j]) % MOD;
    return c;
}

Mat mpow(Mat a, long long e) {
    int n = a.size();
    Mat r(n, vector<long long>(n, 0));
    for (int i = 0; i < n; i++) r[i][i] = 1;
    while (e) {
        if (e & 1) r = mul(r, a);
        a = mul(a, a);
        e >>= 1;
    }
    return r;
}

// P1962 斐波那契：f_n = f_{n-1} + f_{n-2}, f_0=0, f_1=1
long long fib(long long n) {
    if (n == 0) return 0;
    Mat M = {{1, 1}, {1, 0}};
    Mat P = mpow(M, n - 1);          // [f_n, f_{n-1}]^T = M^(n-1) * [f_1, f_0]^T
    return P[0][0];                   // f_n = P[0][0]*f_1 + P[0][1]*f_0 = P[0][0]
}

// P1939 矩阵加速：a[1]=a[2]=a[3]=1, a[n]=a[n-1]+a[n-3]
long long seq(long long n) {
    if (n <= 3) return 1;
    Mat M = {{1, 0, 1}, {1, 0, 0}, {0, 1, 0}};   // 递推 a_n = a_{n-1} + a_{n-3}
    Mat P = mpow(M, n - 3);
    // a_n = P[0][0]*a_3 + P[0][1]*a_2 + P[0][2]*a_1
    return (P[0][0] + P[0][1] + P[0][2]) % MOD;
}

// min-plus 矩阵乘法（广义）：恰好 k 步最短路
Mat mulMinPlus(const Mat& a, const Mat& b) {
    int n = a.size();
    const long long INF = 1e18;
    Mat c(n, vector<long long>(n, INF));
    for (int i = 0; i < n; i++)
        for (int t = 0; t < n; t++) if (a[i][t] < INF)
            for (int j = 0; j < n; j++) if (b[t][j] < INF)
                c[i][j] = min(c[i][j], a[i][t] + b[t][j]);
    return c;
}

int main() {
    cout << "fib(10) = " << fib(10) << endl;   // 55
    cout << "seq(10) = " << seq(10) << endl;   // 19
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// 轮廓线 DP：1x2 多米诺铺满 n×m 的方案数（m ≤ 12）
long long dominoCover(int n, int m) {
    if ((n * m) & 1) return 0;               // 奇数格不可能铺满
    vector<long long> dp(1 << m, 0);
    dp[0] = 1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            vector<long long> ndp(1 << m, 0);
            for (int s = 0; s < (1 << m); s++) {
                if (s >> j & 1) {
                    ndp[s ^ (1 << j)] += dp[s];              // 已被覆盖，直接跳过
                } else {
                    ndp[s | (1 << j)] += dp[s];              // 竖放
                    if (j + 1 < m && !(s >> (j + 1) & 1))
                        ndp[s | (1 << (j + 1))] += dp[s];     // 横放
                }
            }
            dp = ndp;
        }
    }
    return dp[0];
}

int main() {
    cout << "3x4 = " << dominoCover(3, 4) << endl;   // 3
    cout << "4x4 = " << dominoCover(4, 4) << endl;   // 36
    return 0;
}

