#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int N = 5e4 + 5;

int mu[N], sumMu[N], primes[N], cnt;
bool isComp[N];

void sieveMu(int n) {
    mu[1] = 1;
    for (int i = 2; i <= n; i++) {
        if (!isComp[i]) { primes[cnt++] = i; mu[i] = -1; }
        for (int j = 0; j < cnt && (ll)i * primes[j] <= n; j++) {
            isComp[i * primes[j]] = true;
            if (i % primes[j] == 0) { mu[i * primes[j]] = 0; break; }
            else mu[i * primes[j]] = -mu[i];
        }
    }
    for (int i = 1; i <= n; i++) sumMu[i] = sumMu[i-1] + mu[i];
}

// 求 1<=i<=n, 1<=j<=m 中 gcd(i,j)=k 的数对个数
ll countGcd(int n, int m, int k) {
    n /= k; m /= k;
    int t = min(n, m);
    ll ans = 0;
    for (int l = 1, r; l <= t; l = r + 1) {
        r = min(n / (n / l), m / (m / l));
        ans += (ll)(sumMu[r] - sumMu[l-1]) * (n / l) * (m / l);
    }
    return ans;
}

// 求 1<=i<=n, 1<=j<=m 中 gcd(i,j) 为素数的数对个数（YY的GCD）
ll countGcdPrime(int n, int m) {
    int t = min(n, m);
    ll ans = 0;
    // 枚举素数 p，求 gcd=p 的个数
    for (int p : primes) {
        if (p > t) break;
        ans += countGcd(n, m, p);
    }
    return ans;
}

// 数论分块求 sum_{i=1}^{n} floor(n/i)
ll divisorSum(int n) {
    ll ans = 0;
    for (int l = 1, r; l <= n; l = r + 1) {
        r = n / (n / l);
        ans += (ll)(r - l + 1) * (n / l);
    }
    return ans;
}

int main() {
    sieveMu(50000);

    cout << "mu(1)=" << mu[1] << " mu(2)=" << mu[2] << " mu(4)=" << mu[4] << " mu(6)=" << mu[6] << endl;
    // mu(1)=1, mu(2)=-1, mu(4)=0(有平方因子), mu(6)=1(两个素因子)

    cout << "gcd=1 的数对(4,4): " << countGcd(4, 4, 1) << endl;
    // (1,1)(1,2)(1,3)(1,4)(2,1)(2,3)(3,1)(3,2)(3,4)(4,1)(4,3) = 11

    cout << "gcd=2 的数对(4,4): " << countGcd(4, 4, 2) << endl;
    // (2,2)(2,4)(4,2) = 3

    cout << "约数个数和 sum floor(10/i): " << divisorSum(10) << endl;
    // 10+5+3+2+2+1+1+1+1+1 = 27
    return 0;
}

