#include <bits/stdc++.h>
using namespace std;
const int N = 1e5 + 5;

// 可持久化线段树（维护数组）
struct PersistentSegTree {
    struct Node { int l, r, val; } tr[N * 40];
    int cnt;

    int build(int l, int r, int* a) {
        int u = ++cnt;
        if (l == r) { tr[u].val = a[l]; return u; }
        int mid = (l + r) / 2;
        tr[u].l = build(l, mid, a);
        tr[u].r = build(mid+1, r, a);
        return u;
    }

    int update(int prev, int l, int r, int pos, int val) {
        int u = ++cnt;
        tr[u] = tr[prev];
        if (l == r) { tr[u].val = val; return u; }
        int mid = (l + r) / 2;
        if (pos <= mid) tr[u].l = update(tr[prev].l, l, mid, pos, val);
        else tr[u].r = update(tr[prev].r, mid+1, r, pos, val);
        return u;
    }

    int query(int u, int l, int r, int pos) {
        if (l == r) return tr[u].val;
        int mid = (l + r) / 2;
        if (pos <= mid) return query(tr[u].l, l, mid, pos);
        return query(tr[u].r, mid+1, r, pos);
    }
} faTree, szTree;

int n, m;
int rootFa[N], rootSz[N];
int initFa[N], initSz[N];

int find(int root, int x) {
    int fx = faTree.query(root, 1, n, x);
    while (fx != x) {
        x = fx;
        fx = faTree.query(root, 1, n, x);
    }
    return x;
}

bool unite(int ver, int x, int y) {
    int fx = find(rootFa[ver], x);
    int fy = find(rootFa[ver], y);
    if (fx == fy) {
        rootFa[ver+1] = rootFa[ver];
        rootSz[ver+1] = rootSz[ver];
        return false;
    }
    int sx = szTree.query(rootSz[ver], 1, n, fx);
    int sy = szTree.query(rootSz[ver], 1, n, fy);
    if (sx < sy) { swap(fx, fy); swap(sx, sy); }
    rootFa[ver+1] = faTree.update(rootFa[ver], 1, n, fy, fx);
    rootSz[ver+1] = szTree.update(rootSz[ver], 1, n, fx, sx + sy);
    return true;
}

int main() {
    n = 5;
    for (int i = 1; i <= n; i++) { initFa[i] = i; initSz[i] = 1; }
    rootFa[0] = faTree.build(1, n, initFa);
    rootSz[0] = szTree.build(1, n, initSz);

    // 版本1: 合并 1-2
    unite(0, 1, 2);
    // 版本2: 合并 3-4
    unite(1, 3, 4);
    // 版本3: 合并 2-3（连通 1-2-3-4）
    unite(2, 2, 3);

    cout << "版本3: 1和4连通? " << (find(rootFa[3],1) == find(rootFa[3],4)) << endl;  // 1
    cout << "版本2: 1和4连通? " << (find(rootFa[2],1) == find(rootFa[2],4)) << endl;  // 0
    cout << "版本0: 1和2连通? " << (find(rootFa[0],1) == find(rootFa[0],2)) << endl;  // 0
    return 0;
}
